INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q815210', 'Siege of Saguntum', 'The siege of Saguntum took place in 219 BC between the Carthaginians and the Saguntines at the town of Saguntum, near the modern town of Sagunto in the province of Valencia, Spain. The battle is mainly remembered today because it triggered one of the most important wars of antiquity, the Second Punic War.', -219, 5, NULL, -219, 12, NULL, 'month', 'May 219 BCE – December 219 BCE', 63, 'https://en.wikipedia.org/wiki/Siege_of_Saguntum'),
  ('Q6271', 'Second Punic War', 'The Second Punic War (218 to 201 BC) was the second in a series of three wars fought between Carthage and the Roman Republic, who were at the time the two main powers in the western Mediterranean. The protracted war was fought across the region, incurring immense materiel and human losses on both sides.', -218, NULL, NULL, -201, NULL, NULL, 'year', '218 BCE – 201 BCE', 82, 'https://en.wikipedia.org/wiki/Second_Punic_War'),
  ('Q1458235', 'Battle of the Upper Baetis', 'The Battle of the Upper Baetis was a double battle, comprising the battles of Castulo and Ilorca, fought in 211 BC during the Second Punic War between a Carthaginian force led by Hasdrubal Barca (Hannibal''s brother) and a Roman force led by Publius Cornelius Scipio and his brother Gnaeus. The immediate result was a Carthaginian victory in which both Roman brothers were killed.', -211, NULL, NULL, NULL, NULL, NULL, 'year', '211 BCE', 58, 'https://en.wikipedia.org/wiki/Battle_of_the_Upper_Baetis'),
  ('Q1591145', 'Battle of New Carthage', 'The battle of New Carthage took place in early 209 BC when a Roman army under Publius Cornelius Scipio successfully assaulted New Carthage, the capital of Carthaginian Iberia, which was defended by a garrison under Mago. The battle was part of the Second Punic War.', -209, NULL, NULL, NULL, NULL, NULL, 'year', '209 BCE', 58, 'https://en.wikipedia.org/wiki/Battle_of_New_Carthage'),
  ('Q728550', 'Battle of Baecula', 'The Battle of Baecula was a major field battle in Iberia during the Second Punic War. Roman Republican and Iberian auxiliary forces under the command of Scipio Africanus routed the Carthaginian army of Hasdrubal Barca.', -208, NULL, NULL, NULL, NULL, NULL, 'year', '208 BCE', 61, 'https://en.wikipedia.org/wiki/Battle_of_Baecula'),
  ('Q1055755', 'Battle of Ilipa', 'The Battle of Ilipa was an engagement considered by many as Scipio Africanus''s most brilliant victory in his military career during the Second Punic War in 206 BC. It may have taken place on a plain east of Alcalá del Río, Seville, Spain, near the village of Esquivel, the site of the Carthaginian camp. Though it may not seem to be as original as Hannibal''s tactic at Cannae, Scipio''s pre-battle maneuver and his reverse Cannae formation stands as the acme of his tactical ability, in which he permanently broke the Carthaginian grip and source of power in Iberia, thus denying any further land…', -206, NULL, NULL, NULL, NULL, NULL, 'year', '206 BCE', 63, 'https://en.wikipedia.org/wiki/Battle_of_Ilipa'),
  ('Q1503611', 'Numantine War', 'The Numantine War (from Bellum Numantinum in Appian''s Roman History) was the last conflict of the Celtiberian Wars fought by the Romans to subdue those people along the Ebro, in what is now Spain. It was a twenty-year conflict between the Celtiberian tribes of Hispania Citerior and the Roman government.', -143, NULL, NULL, -133, NULL, NULL, 'year', '143 BCE – 133 BCE', 59, 'https://en.wikipedia.org/wiki/Numantine_War'),
  ('Q516760', 'Battle of Munda', 'The Battle of Munda (17 March 45 BC), in southern Hispania Ulterior, was the final battle of Caesar''s civil war against the leaders of the Optimates. With the military victory at Munda and the deaths of Titus Labienus and Gnaeus Pompeius (eldest son of Pompey), Caesar was politically able to return in triumph to Rome, and then govern as the elected Roman dictator.', -45, 3, 17, NULL, NULL, NULL, 'day', '17 March 45 BCE', 66, 'https://en.wikipedia.org/wiki/Battle_of_Munda'),
  ('Q1236473', 'Third Council of Toledo', 'The Third Council of Toledo (589) marks the entry of Visigothic Spain into the Catholic Church, and is known for codifying the filioque clause into Western Christianity. The council also enacted restrictions on Jews, and the conversion of the country to Catholic Christianity led to repeated conflict with the Jews.', 589, NULL, NULL, NULL, NULL, NULL, 'year', '589', 53, 'https://en.wikipedia.org/wiki/Third_Council_of_Toledo'),
  ('Q504172', 'Battle of Guadalete', 'The Battle of Guadalete was the first major battle of the Muslim conquest of the Iberian Peninsula, fought in July 711 at an unidentified location in what is now southern Spain between the Visigoths under their king, Roderic, and the invading forces of the Umayyad Caliphate, composed of mainly Berbers and some Arabs under the commander Tariq ibn Ziyad. The battle was significant as the culmination of a series of Umayyad attacks and the beginning of al-Andalus.', 711, 7, 19, NULL, NULL, NULL, 'day', '19 July 711', 72, 'https://en.wikipedia.org/wiki/Battle_of_Guadalete'),
  ('Q957186', 'Battle of Covadonga', 'The Battle of Covadonga took place in 722 between the army of Pelagius of Asturias and the army of Umayyad Caliphate commanders Alqama and Munuza. Fought near Covadonga, in the Picos de Europa, the outcome was victory for the Christian forces of Pelagius.', 718, NULL, NULL, NULL, NULL, NULL, 'year', '718', 72, 'https://en.wikipedia.org/wiki/Battle_of_Covadonga'),
  ('Q79791', 'Reconquista', 'The Reconquista (Spanish and Portuguese for ''reconquest'') or the fall of al-Andalus was a series of military campaigns by northern Iberian Christian polities against Muslim-ruled al-Andalus, which had been part of the Visigothic Kingdom before the Muslim Conquest of 711. The Reconquista concluded in 1492 with the capture of Granada by the Catholic Monarchs of Spain, thereby ending the presence of any Muslim rule on the Iberian Peninsula.', 722, NULL, NULL, 1492, 1, 2, 'year', '722 – 2 January 1492', 85, 'https://en.wikipedia.org/wiki/Reconquista'),
  ('Q1518266', 'Battle of Simancas', 'The Battle of Simancas (also called Alhandega or al-Khandaq) was a military battle that started on 19 July 939 in the Iberian Peninsula between the troops of the King of León Ramiro II and Cordovan caliph Abd al-Rahman III near the walls of the city of Simancas. The battle unfolded after the army of Abd al-Rahman III launched toward the northern Christian territories in 934.', 939, 7, 19, NULL, NULL, NULL, 'day', '19 July 939', 58, 'https://en.wikipedia.org/wiki/Battle_of_Simancas'),
  ('Q392538', 'Battle of Sagrajas', 'The Battle of Sagrajas (23 October 1086), also called Zalaca or Zallaqah (Arabic: معركة الزلاقة, romanized: Maʿrakat az-Zallāqah), was a conflict fought in 1086 between the Almoravid army, led by their king, Yusuf ibn Tashfin, and the forces of King Alfonso VI of Castile. The Almoravids were called into battle by the taifas, Muslim principalities in Al-Andalus that often fought amongst themselves but united against the expanding Christian kingdoms to the north.', 1086, 10, 23, NULL, NULL, NULL, 'day', '23 October 1086', 72, 'https://en.wikipedia.org/wiki/Battle_of_Sagrajas'),
  ('Q1481920', 'Battle of Alarcos', 'Battle of Alarcos (July 18, 1195) was fought between the Almohads led by Abu Yusuf Ya''qub al-Mansur and King Alfonso VIII of Castile. It resulted in the defeat of the Castilian forces and their subsequent retreat to Toledo, whereas the Almohads reconquered Trujillo, Montánchez, and Talavera.', 1195, 7, 19, NULL, NULL, NULL, 'day', '19 July 1195', 62, 'https://en.wikipedia.org/wiki/Battle_of_Alarcos'),
  ('Q219697', 'Battle of Las Navas de Tolosa', 'The Battle of Las Navas de Tolosa, known in Islamic history as the Battle of Al-Uqab (Arabic: معركة العقاب), took place on 16 July 1212 and was an important turning point in the Reconquista and the history of medieval Spain. The Christian forces were led by King Alfonso VIII of Castile, joined by his rivals, Kings Sancho VII of Navarre and Peter II of Aragon.', 1212, 7, 16, NULL, NULL, NULL, 'day', '16 July 1212', 73, 'https://en.wikipedia.org/wiki/Battle_of_Las_Navas_de_Tolosa'),
  ('Q1792643', 'Battle of Río Salado', 'The Battle of Río Salado also known as the Battle of Tarifa (30 October 1340) was a battle of the allied Christian armies of King Alfonso XI of Castile and King Afonso IV of Portugal against the allied Muslim armies of Sultan Abu al-Hasan ''Ali of the Marinids and Emir Yusuf I of the Emirate of Granada.', 1340, 10, 30, NULL, NULL, NULL, 'day', '30 October 1340', 59, 'https://en.wikipedia.org/wiki/Battle_of_R%C3%ADo_Salado'),
  ('Q221474', 'first arrival of Christopher Columbus to America', 'The human history of the Americas is thought to begin with people migrating to these areas from Asia during the height of an ice age. These groups are generally believed to have been isolated from the people of the "Old World" until the coming of Europeans in 1492 with the voyages of Christopher Columbus.', 1492, 10, 12, NULL, NULL, NULL, 'day', '12 October 1492', 73, 'https://en.wikipedia.org/wiki/Discovery_of_the_Americas'),
  ('Q151663', 'Revolt of the Comuneros', 'The Revolt of the Comuneros (Spanish: Guerra de las Comunidades de Castilla, "War of the Communities of Castile") was an uprising by citizens of Castile against the rule of Charles I and his administration between 1520 and 1521. At its height, the rebels controlled the heart of Castile, ruling the cities of Valladolid, Tordesillas, and Toledo.', 1520, 4, 16, 1522, NULL, NULL, 'day', '16 April 1520 – 1522', 63, 'https://en.wikipedia.org/wiki/Revolt_of_the_Comuneros'),
  ('Q1147471', 'Treaty of Zaragoza', 'The Treaty of Zaragoza or Saragossa, also called the Capitulation of Zaragoza or Saragossa, was a peace treaty between Castile and Portugal, signed on 22 April 1529 by King John III of Portugal and the Habsburg Emperor Charles V in the Aragonese city of Zaragoza. The treaty defined the areas of Castilian and Portuguese influence in Asia in order to resolve the "Moluccas issue", which had arisen because both kingdoms claimed the lucrative Spice Islands (now Indonesia''s Malukus) for themselves, asserting that they were within their area of influence as specified in 1494 by the Treaty of…', 1529, 4, 22, NULL, NULL, NULL, 'day', '22 April 1529', 70, 'https://en.wikipedia.org/wiki/Treaty_of_Zaragoza'),
  ('Q1348955', 'Reapers'' War', 'The Reapers'' War (Catalan: Guerra dels Segadors, Eastern Catalan: [ˈɡɛrə ðəls səɣəˈðos]; Spanish: Guerra de los Segadores, French: Guerre des faucheurs), also known as the Catalan Revolt or Catalan Revolution, was a conflict that affected the Principality of Catalonia between 1640 and 1659, in the context of the Franco-Spanish War of 1635–1659. Incited by an unrest among the Catalan peasantry and institutions, as well as French diplomatic movements, the war resulted in the establishment of the short-lived Catalan Republic and the subsequent clash of Spanish and French armies on Catalan soil…', 1640, 6, 7, 1659, 10, 13, 'day', '7 June 1640 – 13 October 1659', 62, 'https://en.wikipedia.org/wiki/Reapers''_War'),
  ('Q221670', 'Treaty of the Pyrenees', 'The Treaty of the Pyrenees was signed on 7 November 1659 and ended the Franco–Spanish War that had begun in 1635. Negotiations were conducted and the treaty was signed on Pheasant Island, situated in the middle of the Bidasoa River on the border between the two countries, which has remained a French-Spanish condominium ever since.', 1659, 11, 7, NULL, NULL, NULL, 'day', '7 November 1659', 71, 'https://en.wikipedia.org/wiki/Treaty_of_the_Pyrenees'),
  ('Q25857', 'War of Devolution', 'The War of Devolution took place from May 1667 to May 1668. In the course of the war, France occupied large parts of the Spanish Netherlands and Franche-Comté, both then provinces of the Holy Roman Empire ruled by Spain.', 1667, 5, 24, 1668, 5, 2, 'day', '24 May 1667 – 2 May 1668', 69, 'https://en.wikipedia.org/wiki/War_of_Devolution'),
  ('Q311759', 'Battle of Vigo Bay', 'The Battle of Vigo Bay, also known as the Battle of Rande (Galician: Batalla de Rande; Spanish: Batalla de Rande) or sometimes as the Battle of Redondela Bay, was a naval engagement fought on 23 October 1702 during the opening years of the War of the Spanish Succession. The engagement followed an Anglo-Dutch attempt to capture the Spanish port of Cádiz in September in an effort to secure a naval base in the Iberian Peninsula.', 1702, 10, 23, NULL, NULL, NULL, 'day', '23 October 1702', 61, 'https://en.wikipedia.org/wiki/Battle_of_Vigo_Bay'),
  ('Q320394', 'Battle of Almansa', 'The Battle of Almansa took place on 25 April 1707, during the War of the Spanish Succession. It was fought between an army loyal to Philip V of Spain, Bourbon claimant to the Spanish throne, and one supporting his Habsburg rival, Archduke Charles of Austria.', 1707, 4, 25, NULL, NULL, NULL, 'day', '25 April 1707', 62, 'https://en.wikipedia.org/wiki/Battle_of_Almansa'),
  ('Q1422396', 'Treaty of Madrid', 'The Treaty of Madrid (also known as the Treaty of Limits of the Conquests) was an agreement concluded between Spain and Portugal on 13 January 1750. In an effort to end decades of conflict in the region of present-day Uruguay, the treaty established detailed territorial boundaries between Portuguese Brazil and the Spanish colonial territories to the south and west.', 1750, 1, 13, NULL, NULL, NULL, 'day', '13 January 1750', 59, 'https://en.wikipedia.org/wiki/Treaty_of_Madrid_(13_January_1750)'),
  ('Q171416', 'Battle of Trafalgar', 'The Battle of Trafalgar was a fleet action fought on 21 October 1805 off Cape Trafalgar between the Royal Navy and a combined fleet of the French and Spanish navies during the Trafalgar campaign of the War of the Third Coalition. As part of Napoleon''s planned invasion of the United Kingdom, the French and Spanish navies planned to take control of the English Channel and provide the French invasion army with safe passage to England.', 1805, 10, 21, NULL, NULL, NULL, 'day', '21 October 1805', 82, 'https://en.wikipedia.org/wiki/Battle_of_Trafalgar'),
  ('Q152499', 'Peninsular War', 'The Peninsular War (1808–1814) was fought in the Iberian Peninsula by the Iberian nations Spain and Portugal, along with the United Kingdom, against the invading and occupying forces of the First French Empire during the Napoleonic Wars. In Spain, it is considered to overlap with the Spanish War of Independence.', 1808, 5, 2, 1814, 4, 17, 'day', '2 May 1808 – 17 April 1814', 80, 'https://en.wikipedia.org/wiki/Peninsular_War'),
  ('Q155676', 'Battle of Somosierra', 'The Battle of Somosierra took place on 30 November 1808, during the Peninsular War, when a combined Franco-Napoleonic Spanish-Polish force under the direct command of Napoleon I forced a passage through a Spanish division stationed at the Sierra de Guadarrama, which shielded Madrid from direct French attack. At the Somosierra mountain pass, 60 miles (97 km) north of Madrid, a heavily outnumbered Spanish detachment of regulars, volunteers and artillery under Benito de San Juan attempted to block Napoleon''s advance onto Madrid.', 1808, 11, 30, NULL, NULL, NULL, 'day', '30 November 1808', 58, 'https://en.wikipedia.org/wiki/Battle_of_Somosierra'),
  ('Q181146', 'Dos de Mayo Uprising', 'The Dos de Mayo or Second of May Uprising took place in Madrid, Spain, on 2–3 May 1808. The rebellion, mainly by civilians, with some isolated military action by junior officers, was against the occupation of the city by French troops, and was violently repressed by the French Imperial forces, with hundreds of public executions.', 1808, 5, 2, NULL, NULL, NULL, 'day', '2 May 1808', 65, 'https://en.wikipedia.org/wiki/Dos_de_Mayo_Uprising'),
  ('Q1364346', 'Battle of Bailén', 'The Battle of Bailén was fought in 1808 between the Spanish Army''s Army of Andalusia, under General Francisco Javier Castaños and the French Imperial Army''s 2nd Gironde Observational Corps under Divisional-General Pierre Dupont de l''Étang. The first open-field defeat of a Napoleonic army, the battle''s heaviest fighting took place near Bailén (sometimes anglicized as Baylen), a village by the Guadalquivir river in the Jaén province of southern Spain.', 1808, 7, 16, 1808, 7, 19, 'day', '16 July 1808 – 19 July 1808', 61, 'https://en.wikipedia.org/wiki/Battle_of_Bail%C3%A9n'),
  ('Q169023', 'Battle of Talavera', 'The Battle of Talavera (27–28 July 1809) was fought just outside the town of Talavera de la Reina, Spain some 120 kilometres (75 mi) southwest of Madrid, during the Peninsular War. At Talavera, a British army under Sir Arthur Wellesley combined with a Spanish army under General Gregorio García de la Cuesta fought in operations against French-occupied Madrid.', 1809, 7, 27, 1809, 7, 28, 'day', '27 July 1809 – 28 July 1809', 61, 'https://en.wikipedia.org/wiki/Battle_of_Talavera'),
  ('Q708088', 'Battle of Corunna', 'The Battle of Corunna (or A Coruña, La Corunna, La Coruña or La Corogne), in Spain known as Battle of Elviña, took place on 16 January 1809, when a French corps under Marshal of the Empire Jean de Dieu Soult attacked a British army under Lieutenant-General Sir John Moore. The battle took place during the Peninsular War, which was part of the wider Napoleonic Wars.', 1809, 1, 16, NULL, NULL, NULL, 'day', '16 January 1809', 57, 'https://en.wikipedia.org/wiki/Battle_of_Corunna'),
  ('Q689471', 'Battle of Albuera', 'The Battle of Albuera was fought on 16 May 1811 during the Peninsular War. A mixed British, Spanish and Portuguese corps engaged elements of the French armée du Midi (Army of the South) at the small Spanish village of Albuera, about 20 kilometres (12 mi) south of the frontier fortress-town of Badajoz, Spain.', 1811, 5, 16, NULL, NULL, NULL, 'day', '16 May 1811', 58, 'https://en.wikipedia.org/wiki/Battle_of_Albuera'),
  ('Q708580', 'Battle of Salamanca', 'The Battle of Salamanca (in French and Spanish known as the Battle of the Arapiles) took place on 22 July 1812. An Anglo-Portuguese army under the Earl of Wellington (future Duke of Wellington) defeated Marshal Auguste Marmont''s French forces at Arapiles, south of Salamanca, Spain, during the Peninsular War.', 1812, 7, 22, NULL, NULL, NULL, 'day', '22 July 1812', 62, 'https://en.wikipedia.org/wiki/Battle_of_Salamanca'),
  ('Q276059', 'Battle of Vitoria', 'At the Battle of Vitoria (21 June 1813), a British, Portuguese and Spanish army under the Marquess of Wellington broke the French army under King Joseph Bonaparte and Marshal Jean-Baptiste Jourdan near Vitoria in Spain, eventually leading to victory in the Peninsular War.', 1813, 6, 21, NULL, NULL, NULL, 'day', '21 June 1813', 65, 'https://en.wikipedia.org/wiki/Battle_of_Vitoria'),
  ('Q238809', 'Kingdom of Spain (1820-1823)', 'The Trienio Liberal, ([ˈtɾjenjo liβeˈɾal], lit. ''Liberal Triennium'') or Three Liberal Years, was a period of three years in Spain between 1820 and 1823 when a liberal government ruled Spain after a military uprising in January 1820 by the lieutenant-colonel Rafael del Riego against the absolutist rule of Ferdinand VII. It ended in 1823 when, with the approval of the crowned heads of Europe, a French army invaded Spain and reinstated the King''s absolute power.', 1820, 3, 8, 1823, 8, 31, 'day', '8 March 1820 – 31 August 1823', 65, 'https://en.wikipedia.org/wiki/Trienio_Liberal'),
  ('Q1178424', 'Carlist Wars', 'The Carlist Wars (Spanish: guerras carlistas, Basque: karlistadak, Catalan: guerres carlines) were a series of civil wars that took place in Spain during the 19th century. The contenders fought over claims to the throne, although some political differences also existed.', 1833, NULL, NULL, 1876, NULL, NULL, 'year', '1833–1876', 65, 'https://en.wikipedia.org/wiki/Carlist_Wars'),
  ('Q2341073', 'First Carlist War', 'The First Carlist War was a civil war in Spain from 1833 to 1840, the first of three Carlist Wars. It was fought between two factions over the succession to the throne and the nature of the Spanish monarchy: the conservative and devolutionist supporters of the late king''s brother, Carlos de Borbón (or Carlos V), became known as Carlists (carlistas), while the progressive and centralist supporters of the regent, Maria Christina, acting for Isabella II of Spain, were called Liberals (liberales), cristinos or isabelinos.', 1833, 10, 2, 1840, 7, 6, 'day', '2 October 1833 – 6 July 1840', 65, 'https://en.wikipedia.org/wiki/First_Carlist_War'),
  ('Q1142553', 'Tragic Week', 'The Tragic Week (in Catalan la Setmana Tràgica, in Spanish la Semana Trágica) (25 July – 2 August 1909) was a series of violent confrontations between the Spanish army and anarchists, freemasons, socialists and republicans of Barcelona and other cities in Catalonia, Spain, during the last week of July 1909. It was caused by the calling-up of reserve troops by Premier Antonio Maura to be sent as reinforcements when Spain renewed military-colonial activity in Morocco on 9 July, in what is known as the Second Rif War.', 1909, NULL, NULL, 1909, 8, 2, 'year', '1909', 61, 'https://en.wikipedia.org/wiki/Tragic_Week_(Spain)'),
  ('Q2745432', 'Spanish Constitution of 1931', 'The Spanish Constitution of 1931 was approved by the Constituent Assembly on 9 December 1931. It was the constitution of the Second Spanish Republic (founded 14 April 1931) and was in force until 1 April 1939.', 1931, NULL, NULL, NULL, NULL, NULL, 'year', '1931', 57, 'https://en.wikipedia.org/wiki/Spanish_Constitution_of_1931'),
  ('Q10859', 'Spanish Civil War', 'The Spanish Civil War (Spanish: guerra civil española) was fought in Spain from 1936 to 1939 between the Republicans and the Nationalist rebels. Republicans loyal to the left-leaning Popular Front government of the Second Spanish Republic included socialists, anarchists, communists, and separatists, supported by the Soviet Union.', 1936, 7, 18, 1939, 4, 1, 'day', '18 July 1936 – 1 April 1939', 92, 'https://en.wikipedia.org/wiki/Spanish_Civil_War'),
  ('Q685062', 'Siege of Madrid', 'The siege of Madrid was a two-and-a-half-year siege of the Republican-controlled Spanish capital city of Madrid by the Nationalist armies, under General Francisco Franco, during the Spanish Civil War (1936–1939). The city, besieged from October 1936, fell to the Nationalist armies on 28 March 1939.', 1936, 11, 8, 1936, 11, 23, 'day', '8 November 1936 – 23 November 1936', 62, 'https://en.wikipedia.org/wiki/Siege_of_Madrid'),
  ('Q815108', 'Siege of the Alcázar', 'The siege of the Alcázar was a highly symbolic Nationalist victory in Toledo in the opening stages of the Spanish Civil War. The Alcázar of Toledo was held by a variety of military forces in favor of the Nationalists.', 1936, NULL, NULL, 1936, 9, 27, 'year', '1936', 58, 'https://en.wikipedia.org/wiki/Siege_of_the_Alc%C3%A1zar'),
  ('Q1467456', 'Battle of Teruel', 'The Battle of Teruel was fought in and around the city of Teruel during the Spanish Civil War between December 1937 and February 1938, during the worst Spanish winter in 20 years. The battle was one of the bloodiest actions of the war, with the city changing hands several times by first falling to the Republicans and eventually being retaken by the Nationalists.', 1937, 12, 15, 1938, 2, 22, 'day', '15 December 1937 – 22 February 1938', 59, 'https://en.wikipedia.org/wiki/Battle_of_Teruel'),
  ('Q1641241', 'Battle of Guadalajara', 'The Battle of Guadalajara (8–23 March 1937) saw the victory of the Spanish Republican Army (Ejército Popular Republicano, or EPR) and of the International Brigades over the Italian and Nationalist forces attempting to encircle Madrid during the Spanish Civil War. The Nationalist forces involved in the Battle of Guadalajara were primarily the Italian Corps of Volunteer Troops (Corpo Truppe Volontarie, or CTV).', 1937, NULL, NULL, 1937, 3, 23, 'year', '1937', 58, 'https://en.wikipedia.org/wiki/Battle_of_Guadalajara'),
  ('Q1885246', 'Barcelona May Days', 'The May Days, sometimes also called May Events, were a series of clashes between 3 and 8 May 1937 during which factions on the Republican side of the Spanish Civil War engaged one another in street battles in various parts of Catalonia, centered on the city of Barcelona. In those events, libertarian socialist supporters of the Spanish Revolution, such as the anarchist CNT and the anti-Stalinist POUM, which opposed a centralized government, faced others, such as the Republican government, Catalan government and the Communist Party of Spain, which believed in a strong central government.', 1937, 5, 3, 1937, 5, 8, 'day', '3 May 1937 – 8 May 1937', 57, 'https://en.wikipedia.org/wiki/May_Days'),
  ('Q1280119', 'Battle of the Ebro', 'The Battle of the Ebro (Spanish: Batalla del Ebro, Catalan: Batalla de l''Ebre) was the longest and largest battle of the Spanish Civil War and the greatest, in terms of manpower, logistics and material ever fought on Spanish soil. It took place between July and November 1938, with fighting mainly concentrated in two areas on the lower course of the Ebro River, the Terra Alta comarca of Catalonia, and the Auts area close to Fayón (Faió) in the lower Matarranya, Eastern Lower Aragon.', 1938, 7, 25, 1938, 11, 16, 'day', '25 July 1938 – 16 November 1938', 61, 'https://en.wikipedia.org/wiki/Battle_of_the_Ebro'),
  ('Q113382', '1966 Palomares B-52 crash', 'The Palomares accident occurred on 17 January 1966, when a United States Air Force B-52G bomber collided with a KC-135 tanker during mid-air refueling at 31,000 feet (9,450 m) over the Mediterranean Sea, near the Spanish village of Palomares in Almería province. The collision destroyed the tanker, killing all four crew members, and caused the bomber to break apart, resulting in the deaths of three of its seven crew members.', 1966, 1, 17, NULL, NULL, NULL, 'day', '17 January 1966', 62, 'https://en.wikipedia.org/wiki/1966_Palomares_accident'),
  ('Q874209', 'Spanish transition to democracy', 'The Spanish transition to democracy, known in Spain as la Transición (IPA: [la tɾansiˈθjon]; ''the Transition'') or la Transición española (''the Spanish Transition''), officially the Spanish State from 1975 to 1978 and Kingdom of Spain thereafter, was a period of modern Spanish history encompassing the regime change that moved from the Francoist dictatorship to the consolidation of a parliamentary system, in the form of constitutional monarchy under Juan Carlos I. The democratic transition began two days after the death of Francisco Franco, in November 1975. Initially, "the political elites…', 1975, 11, 20, 1983, NULL, NULL, 'day', '20 November 1975 – 1980s', 70, 'https://en.wikipedia.org/wiki/Spanish_transition_to_democracy'),
  ('Q223288', 'Tenerife airport disaster', 'On March 27, 1977, two Boeing 747 passenger jets collided on a runway at Los Rodeos Airport on the Spanish island of Tenerife, killing 583 people and injuring 61 others in the deadliest accident in aviation history. The incident occurred at 17:06 GMT (UTC +0) in dense fog, when KLM Flight 4805 initiated its takeoff run, colliding with the right side of Pan Am Flight 1736, which was on the runway.', 1977, 3, 27, NULL, NULL, NULL, 'day', '27 March 1977', 75, 'https://en.wikipedia.org/wiki/Tenerife_airport_disaster'),
  ('Q847664', 'constitution of Spain', 'The Spanish Constitution (Spanish: Constitución Española) is the supreme law of the Kingdom of Spain. It was enacted after its approval in 1978 in a constitutional referendum; it represents the culmination of the Spanish transition to democracy.', 1978, 12, 29, NULL, NULL, NULL, 'day', '29 December 1978', 73, 'https://en.wikipedia.org/wiki/Constitution_of_Spain'),
  ('Q213531', '2004 Madrid train bombings', 'The 2004 Madrid train bombings (also known in Spain as 11M for 11 de marzo) (or 3/11) were a series of coordinated, nearly simultaneous bombings against the Cercanías commuter train system of Madrid, Spain, on the morning of 11 March 2004—three days before Spain''s general elections. The explosions killed 193 people and injured around 2,500.', 2004, 3, 11, NULL, NULL, NULL, 'day', '11 March 2004', 74, 'https://en.wikipedia.org/wiki/2004_Madrid_train_bombings'),
  ('Q152758', 'Spanair Flight 5022', 'Spanair Flight 5022 was a scheduled domestic passenger flight from Barcelona–El Prat Airport to Gran Canaria Airport, Spain, with a stopover in Madrid–Barajas Airport that crashed just after take-off from runway 36L at Madrid-Barajas Airport at 14:24 CEST (12:24 UTC) on 20 August 2008. The aircraft was a McDonnell Douglas MD-82, registration EC-HFP. Of the 172 passengers and crew on board, 154 died and 18 survived.', 2008, 8, 20, NULL, NULL, NULL, 'day', '20 August 2008', 67, 'https://en.wikipedia.org/wiki/Spanair_Flight_5022'),
  ('Q584613', '2011 Lorca earthquake', 'The 2011 Lorca earthquake (Spanish: Terremoto de Lorca de 2011) was a moderate 5.1 Mw earthquake that occurred 18:47 CEST (16:47 UTC) on 11 May 2011, near the town of Lorca, causing significant localized damage in the Region of Murcia, Spain, and panic among locals, and displacing many from their homes. The quake was preceded by a magnitude 4.4 (Mw) foreshock at 17:05 (15:05 UTC), that inflicted substantial damage to many older structures in the area, including the historical Espolón Tower of Lorca Castle, the Hermitage of San Clemente and the Convent of Virgen de Las Huertas.', 2011, 5, 11, NULL, NULL, NULL, 'day', '11 May 2011', 65, 'https://en.wikipedia.org/wiki/2011_Lorca_earthquake'),
  ('Q735377', '2011–2012 Spanish protests', 'The anti-austerity movement in Spain, also referred to as the 15-M Movement (Spanish: Movimiento 15-M), and the Indignados Movement, was a series of protests, demonstrations, and occupations against austerity policies in Spain that began around the local and regional elections of 2011 and 2012. Beginning on 15 May 2011, many of the subsequent demonstrations spread through various social networks such as Real Democracy NOW (Spanish: Democracia Real YA) and Youth Without a Future (Spanish: Juventud Sin Futuro).', 2011, 5, 15, NULL, NULL, NULL, 'day', '15 May 2011', 63, 'https://en.wikipedia.org/wiki/Anti-austerity_movement_in_Spain'),
  ('Q15989108', 'Western African Ebola virus epidemic', 'The 2013–2016 epidemic of Ebola virus disease, centered in West Africa, was the most widespread outbreak of the disease in history. It caused major loss of life and socioeconomic disruption in the region, mainly in Guinea, Liberia and Sierra Leone.', 2013, 12, NULL, 2016, 6, NULL, 'month', 'December 2013 – June 2016', 78, 'https://en.wikipedia.org/wiki/Western_African_Ebola_epidemic'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q130731262', '2024 Spain floods', 'On 29 October 2024, torrential rain caused by an isolated low-pressure area at high levels brought over a year''s worth of precipitation to several areas in eastern Spain, including the Valencian Community, Castilla–La Mancha, and Andalusia. The resulting floodwaters caused the deaths of at least 242 people and substantial property damage.', 2024, 10, 29, NULL, NULL, NULL, 'day', '29 October 2024', 71, 'https://en.wikipedia.org/wiki/2024_Spanish_floods');
